#!/bin/bash
# Applies the canonical language list (ADR-0017) to the built app: copies the InfoPlist.strings
# bundles generated by :app:shared:generateIosAppLocalizations and writes CFBundleLocalizations
# into the already-processed Info.plist. Runs as the last build phase, after Xcode's own
# "Process Info.plist" / "Copy Bundle Resources" steps.
set -euo pipefail

GENERATED_DIR="${SRCROOT}/../app/shared/build/generated/iosAppLocalizations"
LOCALES_FILE="${GENERATED_DIR}/app-localizations.txt"
BUILT_INFOPLIST="${TARGET_BUILD_DIR}/${INFOPLIST_PATH}"
RESOURCES_DIR="${TARGET_BUILD_DIR}/${UNLOCALIZED_RESOURCES_FOLDER_PATH}"
PLIST_BUDDY=/usr/libexec/PlistBuddy

if [ ! -f "${LOCALES_FILE}" ]; then
  echo "error: ${LOCALES_FILE} not found. Run :app:shared:generateIosAppLocalizations first." >&2
  exit 1
fi

if [ ! -f "${BUILT_INFOPLIST}" ]; then
  echo "error: built Info.plist not found at ${BUILT_INFOPLIST}." >&2
  exit 1
fi

"${PLIST_BUDDY}" -c "Delete :CFBundleLocalizations" "${BUILT_INFOPLIST}" >/dev/null 2>&1 || true
"${PLIST_BUDDY}" -c "Add :CFBundleLocalizations array" "${BUILT_INFOPLIST}"

while IFS= read -r TAG || [ -n "${TAG}" ]; do
  [ -z "${TAG}" ] && continue

  LPROJ_DIR="${RESOURCES_DIR}/${TAG}.lproj"
  mkdir -p "${LPROJ_DIR}"
  cp "${GENERATED_DIR}/${TAG}.lproj/InfoPlist.strings" "${LPROJ_DIR}/InfoPlist.strings"

  "${PLIST_BUDDY}" -c "Add :CFBundleLocalizations: string ${TAG}" "${BUILT_INFOPLIST}"
done < "${LOCALES_FILE}"
